function suggestedGuide(){const preg=state.profile?.mode==='pregnancy';const week=preg?pregnancyInfo(state.profile.birthDate).week:0;return libraryGuides.find(g=>g.stage===(preg?'pregnancy':'born')&&(!g.weekMin||week>=g.weekMin)&&(!g.weekMax||week<=g.weekMax)&&!(state.readGuides||[]).includes(g.id))||libraryGuides.find(g=>g.stage==='all'&&!(state.readGuides||[]).includes(g.id))||libraryGuides[0]}
function renderRecommendedGuide(){const box=$('recommendedGuide');if(!box)return;const g=suggestedGuide();$('recommendedGuideTitle').textContent=g.title;$('recommendedGuideText').textContent=`${g.summary} · ${g.minutes} min di lettura`;$('recommendedGuideBtn').onclick=()=>{showView('biblioteca');setTimeout(()=>openGuide(g.id),100)}}
function openGuide(id){const g=libraryGuides.find(x=>x.id===id);if(!g)return;state.readGuides=state.readGuides||[];if(!state.readGuides.includes(id)){state.readGuides.push(id);persist()}const card=document.querySelector(`[data-guide-card="${id}"]`);if(card){card.classList.add('open');card.scrollIntoView({behavior:'smooth',block:'start'})}}
function renderLibrary(){if(!$('libraryList'))return;state.favoriteGuides=state.favoriteGuides||[];state.readGuides=state.readGuides||[];const q=($('librarySearch')?.value||'').toLowerCase().trim(),cat=$('libraryCategory')?.value||'all',favOnly=$('libraryFavoritesOnly')?.checked;const list=libraryGuides.filter(g=>(cat==='all'||g.category===cat)&&(!favOnly||state.favoriteGuides.includes(g.id))&&(!q||[g.title,g.summary,g.category,...g.sections.flat()].join(' ').toLowerCase().includes(q)));$('libraryStats').innerHTML=`<span><strong>${libraryGuides.length}</strong> guide offline</span><span><strong>${state.favoriteGuides.length}</strong> preferite</span><span><strong>${state.readGuides.length}</strong> lette</span>`;$('libraryList').innerHTML=list.map(g=>`<article class="library-card ${state.readGuides.includes(g.id)?'read':''}" data-guide-card="${g.id}"><div class="library-card-head"><div><span class="section-kicker">${esc(g.category)}</span><h2>${esc(g.title)}</h2></div><button class="favorite-btn ${state.favoriteGuides.includes(g.id)?'active':''}" data-guide-fav="${g.id}" aria-label="Preferito">${state.favoriteGuides.includes(g.id)?'★':'☆'}</button></div><p>${esc(g.summary)}</p><div class="guide-meta"><span>⏱ ${g.minutes} min</span><span>${state.readGuides.includes(g.id)?'✓ Letta':'Da leggere'}</span></div><button class="soft-btn" data-guide-open="${g.id}">Leggi la guida</button><div class="guide-content">${g.sections.map(s=>`<section><h3>${esc(s[0])}</h3><p>${esc(s[1])}</p></section>`).join('')}<div class="guide-source"><strong>Fonti di riferimento:</strong> ${esc(g.sources)}<br><small>Aggiornata il ${fmtDate(g.updated)}</small></div></div></article>`).join('')||'<div class="empty-state">Nessuna guida corrisponde alla ricerca.</div>';document.querySelectorAll('[data-guide-open]').forEach(b=>b.onclick=()=>openGuide(b.dataset.guideOpen));document.querySelectorAll('[data-guide-fav]').forEach(b=>b.onclick=()=>{const id=b.dataset.guideFav;state.favoriteGuides=state.favoriteGuides.includes(id)?state.favoriteGuides.filter(x=>x!==id):[...state.favoriteGuides,id];persist()})}

