const emptyState=()=>({profile:null,completed:[],documents:defaultDocuments.map((name,i)=>({id:'doc-'+i,name,category:'Da classificare',status:'Manca',done:false,date:'',expiry:'',visitId:'',notes:''})),deadlines:[],health:[],school:[],benefits:defaultBenefits.map((title,i)=>({id:'ben-'+i,title,status:'Da verificare',notes:''})),expenses:[],diary:[],pregnancyNotes:[],visits:[],birthPrep:defaultBirthPrep.map(x=>({...x,done:false,custom:false,notes:''})),diagnosisSupport:defaultDiagnosisSupport.map(x=>({...x,notes:''})),favoriteGuides:[],readGuides:[],assistantMessages:[],members:[],activeMemberId:'',preferences:{theme:'system',textSize:'normal',highContrast:false,largeIcons:false},syncMeta:{status:'local',lastSuccess:'',lastAttempt:'',pending:false,retries:0,revision:0,error:''},activityLog:[]});
let state=Object.assign(emptyState(),JSON.parse(localStorage.getItem('pdp_state')||'{}'));state.preferences={...emptyState().preferences,...(state.preferences||{})};state.syncMeta={...emptyState().syncMeta,...(state.syncMeta||{})};state.activityLog=state.activityLog||[];state.members=state.members||[];if(state.profile&&!state.members.length){const id='owner-'+(state.profile.familyCode||'family');state.members=[{id,name:'Genitore',role:'Genitore',permission:'owner'}];state.activeMemberId=id}state.documents=(state.documents||[]).map(d=>({...d,status:d.status||(d.done?'Completo':'Manca'),done:(d.status?d.status==='Completo':!!d.done),expiry:d.expiry||'',visitId:d.visitId||'',notes:d.notes||'',fileName:d.fileName||'',fileType:d.fileType||'',fileSize:d.fileSize||0,extractedText:d.extractedText||'',driveFileId:d.driveFileId||'',driveUrl:d.driveUrl||'',driveUploadedAt:d.driveUploadedAt||''}));let syncTimer=null,deferredPrompt=null;
function activity(action,detail=''){
  state.activityLog=state.activityLog||[];
  const user=window.PDP_CLOUD?.getMember?.();
  state.activityLog.unshift({id:uid(),at:new Date().toISOString(),action,detail,by:user?.name||'Utente'});
  state.activityLog=state.activityLog.slice(0,100);
}
function saveLocal(){localStorage.setItem('pdp_state',JSON.stringify(state))}
function persist(sync=true){
  state.syncMeta={...emptyState().syncMeta,...(state.syncMeta||{})};
  if(sync){state.syncMeta.pending=true;state.syncMeta.status=navigator.onLine?'pending':'offline';state.syncMeta.error=''}
  saveLocal();renderAll();if(!sync)return;
  clearTimeout(syncTimer);syncTimer=setTimeout(()=>performCloudSync(false),700);
}
function snapshot(){return {...state,updatedAt:new Date().toISOString()}}
function formatSyncTime(value){if(!value)return'';try{return new Date(value).toLocaleString('it-IT')}catch{return''}}
function setSyncStatus(text,type=''){
  if($('syncStatus'))$('syncStatus').textContent=text;
  if($('syncDot'))$('syncDot').className='sync-dot '+type;
  if($('syncDetails'))$('syncDetails').textContent=state.syncMeta?.lastSuccess?'Ultima sincronizzazione: '+formatSyncTime(state.syncMeta.lastSuccess):'Nessuna sincronizzazione completata';
}
function refreshSyncUi(){
  const m=state.syncMeta||{};
  if(m.status==='syncing')setSyncStatus('Sincronizzazione…');
  else if(m.status==='ok')setSyncStatus('Sincronizzato','ok');
  else if(m.status==='error')setSyncStatus('Errore di sincronizzazione','error');
  else if(m.status==='offline')setSyncStatus('Offline: salvato sul dispositivo','error');
  else if(m.pending)setSyncStatus('Modifiche da sincronizzare');
  else setSyncStatus('Solo sul dispositivo');
}
async function performCloudSync(show=true,force=false){
  state.syncMeta={...emptyState().syncMeta,...(state.syncMeta||{}),lastAttempt:new Date().toISOString()};
  if(!navigator.onLine){state.syncMeta.status='offline';state.syncMeta.pending=true;saveLocal();refreshSyncUi();return false}
  if(window.PDP_CLOUD?.isReady?.()){
    state.syncMeta.status='syncing';saveLocal();refreshSyncUi();
    try{
      const result=await window.PDP_CLOUD.save(snapshot(),{baseRevision:state.syncMeta.revision||window.PDP_CLOUD.getRevision?.()||0,force});
      state.syncMeta={...state.syncMeta,status:'ok',pending:false,retries:0,error:'',lastSuccess:new Date().toISOString(),revision:result?.revision||window.PDP_CLOUD.getRevision?.()||state.syncMeta.revision};
      activity('Sincronizzazione completata','Dati salvati nel cloud');saveLocal();renderActivityLog();refreshSyncUi();
      if(show)alert('Sincronizzazione completata.');return true;
    }catch(e){
      if(e.code==='pdp/conflict'){
        state.syncMeta.status='conflict';state.syncMeta.pending=true;state.syncMeta.error=e.message;saveLocal();
        const useRemote=confirm('Un altro dispositivo ha salvato modifiche più recenti.\n\nOK: scarica la versione cloud.\nAnnulla: conserva questa versione e riprova manualmente.');
        if(useRemote){await window.PDP_CLOUD.reload();state.syncMeta={...state.syncMeta,status:'ok',pending:false,error:'',lastSuccess:new Date().toISOString(),revision:window.PDP_CLOUD.getRevision?.()||0};saveLocal();refreshSyncUi();}
        else{setSyncStatus('Conflitto da risolvere','error')}
        return false;
      }
      state.syncMeta.status='error';state.syncMeta.pending=true;state.syncMeta.retries=(state.syncMeta.retries||0)+1;state.syncMeta.error=e.message||String(e);saveLocal();refreshSyncUi();
      if(show)alert('Dati conservati sul dispositivo. Sincronizzazione non riuscita: '+state.syncMeta.error);
      scheduleRetry();return false;
    }
  }
  if(state.profile?.familyCode&&apiConfigured())return syncToLegacyGoogle(show);
  state.syncMeta.status='local';saveLocal();refreshSyncUi();return false;
}
let retryTimer=null;
function scheduleRetry(){clearTimeout(retryTimer);const n=Math.min(state.syncMeta?.retries||1,6);retryTimer=setTimeout(()=>performCloudSync(false),Math.min(60000,3000*Math.pow(2,n-1)))}
async function syncToLegacyGoogle(show=true){
  if(!apiConfigured()){state.syncMeta.status='local';saveLocal();refreshSyncUi();return false}
  try{const r=await fetch(API_URL,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:'save',familyCode:state.profile.familyCode,data:snapshot()})});const j=await r.json();if(!j.ok)throw new Error(j.error||'Errore');state.syncMeta={...state.syncMeta,status:'ok',pending:false,lastSuccess:new Date().toISOString(),error:''};saveLocal();refreshSyncUi();return true}catch(e){state.syncMeta.status='error';state.syncMeta.error=e.message;saveLocal();refreshSyncUi();if(show)alert(e.message);return false}
}
async function syncToGoogle(show=true){return performCloudSync(show)}
async function loadFromGoogle(show=true){
  if(window.PDP_CLOUD?.isReady?.()){state.syncMeta.status='syncing';refreshSyncUi();try{await window.PDP_CLOUD.reload();state.syncMeta={...state.syncMeta,status:'ok',pending:false,lastSuccess:new Date().toISOString(),revision:window.PDP_CLOUD.getRevision?.()||0,error:''};saveLocal();refreshSyncUi();if(show)alert('Dati aggiornati dal cloud.')}catch(e){state.syncMeta.status='error';state.syncMeta.error=e.message;saveLocal();refreshSyncUi();if(show)alert(e.message)}return}
  if(!apiConfigured()||!state.profile?.familyCode)return;
}
function ageText(date){if(!date)return'';const b=new Date(date+'T00:00:00'),t=new Date();if(b>t){const d=Math.ceil((b-t)/86400000);return`Nascita prevista tra circa ${d} giorni`}let y=t.getFullYear()-b.getFullYear(),m=t.getMonth()-b.getMonth();if(t.getDate()<b.getDate())m--;if(m<0){y--;m+=12}return y<1?`${Math.max(0,m)} mesi`:`${y} anni e ${Math.max(0,m)} mesi`}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function fmtDate(d){return d?new Date(d+'T00:00:00').toLocaleDateString('it-IT'):'—'}
function uid(){return crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random()}
