function pregnancyInfo(dueDate){const due=new Date(dueDate+'T00:00:00'),now=new Date();const conception=new Date(due);conception.setDate(conception.getDate()-280);const elapsed=Math.floor((now-conception)/86400000);const week=Math.max(1,Math.min(40,Math.floor(elapsed/7)+1));const daysLeft=Math.max(0,Math.ceil((due-now)/86400000));return{week,daysLeft,pct:Math.max(2,Math.min(100,Math.round(elapsed/280*100)))}}
function pregnancyLabel(date){const i=pregnancyInfo(date);return`${i.week}ª settimana di gravidanza`}
function activeItems(){if(state.profile?.mode!=='pregnancy')return journeyItems;const w=pregnancyInfo(state.profile.birthDate).week;return pregnancyItems.filter(x=>x.week<=w+6)}
function nextJourneyItem(){const items=state.profile?.mode==='pregnancy'?activeItems():journeyItems;return items.find(x=>!state.completed.includes(x.id))||null}
function renderPregnancy(){const box=$('pregnancyHero');if(!box)return;if(state.profile.mode!=='pregnancy'){box.classList.add('hidden');return}box.classList.remove('hidden');const i=pregnancyInfo(state.profile.birthDate),next=nextJourneyItem();$('pregnancyWeek').textContent=`${i.week}ª settimana di gravidanza`;$('pregnancyCountdown').textContent=i.daysLeft?`Mancano circa ${i.daysLeft} giorni alla data presunta del parto.`:'La data presunta del parto è arrivata.';$('pregnancyBar').style.width=i.pct+'%';$('pregnancyProgressText').textContent=`Percorso completato al ${i.pct}% · data presunta ${fmtDate(state.profile.birthDate)}`;$('nextStepTitle').textContent=next?.title||'Avete completato le tappe disponibili';$('nextStepMeta').textContent=next?`${next.meta} · circa 5 minuti`:'Continuate ad aggiornare diario e appuntamenti';$('startNextStep').onclick=()=>showView(next?.group==='Diario'?'diario':'checklist')}
function renderTimeline(){if(!$('journeyTimeline'))return;const isPreg=state.profile.mode==='pregnancy',info=isPreg?pregnancyInfo(state.profile.birthDate):null;const items=isPreg?pregnancyItems:journeyItems;$('journeySubtitle').textContent=isPreg?`Siete alla ${info.week}ª settimana. Le indicazioni sanitarie vanno sempre concordate con i professionisti che seguono la gravidanza.`:'Dalla nascita ai 18 anni, con le vostre tappe.';$('journeyTimeline').innerHTML=items.map(x=>{const done=state.completed.includes(x.id),current=isPreg&&!done&&x.week<=info.week+2&&x.week>=info.week-2;return`<div class="timeline-item ${done?'done':current?'current':''}"><span class="timeline-dot"></span><div class="timeline-card"><h3>${done?'✓ ':''}${esc(x.title)}</h3><small>${esc(x.meta)}</small><p>${esc(x.description)}</p>${!done?`<button class="soft-btn" data-timeline-check="${x.id}">Segna come completato</button>`:''}</div></div>`}).join('');document.querySelectorAll('[data-timeline-check]').forEach(b=>b.onclick=()=>toggleCompleted(b.dataset.timelineCheck))}
function daysBetweenToday(date){const today=new Date();today.setHours(0,0,0,0);const d=new Date(date+'T00:00:00');return Math.ceil((d-today)/86400000)}
function getTodayPriority(){
  if(state.profile?.mode==='pregnancy'){const next=(state.diagnosisSupport||[]).find(x=>!x.done);if(next)return{level:'Prossima',title:'Un passo alla volta',message:next.title,details:[next.category,next.description],time:'circa 5 minuti',view:'diagnosi'};}
 const today=new Date().toISOString().slice(0,10);
 const visits=(state.visits||[]).filter(v=>v.date>=today).sort((a,b)=>a.date.localeCompare(b.date));
 const nextVisit=visits[0];
 if(nextVisit){const days=daysBetweenToday(nextVisit.date);if(days<=7){const missing=[];if(!nextVisit.documents)missing.push('preparare i documenti da portare');if(!nextVisit.questions)missing.push('scrivere le domande da fare');if(missing.length)return{level:days<=2?'Urgente':'Prossima',title:days===0?'La visita è oggi':days===1?'La visita è domani':`Visita tra ${days} giorni`,message:`${nextVisit.title}${nextVisit.specialist?' · '+nextVisit.specialist:''}`,details:missing.map(x=>'⬜ '+x),time:'circa 10 minuti',view:'visite'};return{level:days<=2?'Urgente':'Prossima',title:days===0?'La visita è oggi':days===1?'La visita è domani':`Prepariamo la visita tra ${days} giorni`,message:nextVisit.title,details:['✔ Documenti da portare registrati','✔ Domande già preparate'],time:'circa 5 minuti',view:'visite'}}}
 if(state.profile?.mode==='pregnancy'){
  const due=pregnancyInfo(state.profile.birthDate),prep=(state.birthPrep||[]).find(x=>!x.done&&birthPrepAvailable(x));
  if(prep&&due.daysLeft<=60)return{level:due.daysLeft<=30?'Urgente':'Prossima',title:'Prepariamoci alla nascita',message:prep.title,details:[`Categoria: ${prep.category}`,'Completa una piccola attività alla volta'],time:'circa 10 minuti',view:'preparazione'};
 }
 const docs=(state.documents||[]).filter(d=>d.status==='Manca'||(!d.status&&!d.done));
 if(docs.length)return{level:'Priorità',title:'Completiamo un documento importante',message:`Risultano ${docs.length} documenti ancora mancanti. Iniziamo da “${docs[0].name}”.`,details:['⬜ Verifica cosa manca','⬜ Aggiorna lo stato del documento'],time:'circa 5 minuti',view:'documenti'};
 if(state.profile?.mode==='pregnancy'){
  const info=pregnancyInfo(state.profile.birthDate),latest=[...(state.pregnancyNotes||[])].sort((a,b)=>(b.date||'').localeCompare(a.date||''))[0];
  if(!latest||Number(latest.week)!==Number(info.week))return{level:'Questa settimana',title:`Conserviamo un ricordo della ${info.week}ª settimana`,message:'Aggiorna il diario con come state, un momento da ricordare e le domande per il prossimo controllo.',details:['⬜ Come sta la mamma','⬜ Come sta il papà','⬜ Domande per il medico'],time:'circa 5 minuti',view:'diario'};
 }
 const next=nextJourneyItem();if(next)return{level:'Prossimo passo',title:next.title,message:next.description,details:[`⬜ ${next.group}`,`Periodo: ${next.meta}`],time:'circa 5 minuti',view:next.group==='Diario'?'diario':'checklist',itemId:next.id};
 return{level:'Tutto in ordine',title:'Avete completato le priorità disponibili',message:'Potete controllare il calendario oppure aggiungere un ricordo al diario.',details:['✔ Nessuna urgenza rilevata'],time:'quando volete',view:'calendario'};
}
function renderTodayAssistant(){const box=$('todayAssistant');if(!box)return;const p=getTodayPriority();$('todayAssistantTitle').textContent=p.title;$('todayAssistantMessage').textContent=p.message;$('todayAssistantDetails').innerHTML=(p.details||[]).map(x=>`<div>${esc(x)}</div>`).join('');$('todayAssistantTime').textContent=`Tempo richiesto: ${p.time}`;$('todayPriorityBadge').textContent=p.level;$('todayPriorityBadge').className='badge '+(p.level==='Urgente'?'urgent':p.level==='Prossima'?'soon':'');$('todayAssistantAction').onclick=()=>showView(p.view)}
