$('todayList').innerHTML=pending.length?pending.map((x,i)=>`<div class="compact-item ${i===0?'is-urgent':i===1?'is-soon':''}"><input type="checkbox" data-check="${x.id}" aria-label="Completa ${esc(x.title)}"><div class="grow"><strong>${esc(x.title)}</strong><br><small>${esc(x.group)} · ${esc(x.meta)}</small></div><span class="badge ${i===0?'urgent':i===1?'soon':''}">${i===0?'Priorità':i===1?'Prossima':'Da fare'}</span></div>`).join(''):'<div class="empty-state">Hai completato tutte le attività della checklist.</div>';
