$('progressList').innerHTML=groups.map(g=>{const all=dashboardItems.filter(x=>x.group===g),done=all.filter(x=>state.completed.includes(x.id)).length,pct=Math.round(done/all.length*100);return`<div class="progress-block"><div class="progress-label"><span>${esc(g)}</span><span>${done}/${all.length}</span></div><div class="progress-track" aria-label="${esc(g)} ${pct}%"><div class="progress-bar" style="width:${pct}%"></div></div></div>`}).join('');
