$('visitList').innerHTML=entries.map(x=>`<article class="visit-card"><div class="visit-date"><strong>${new Date(x.date+'T00:00:00').getDate()}</strong><small>${new Date(x.date+'T00:00:00').toLocaleDateString('it-IT',{month:'short'}).toUpperCase()}</small></div><div class="card-main"><div class="visit-head"><div><h3>${esc(x.title)}</h3><small>${esc(x.time||'Orario da definire')} · ${esc(x.specialist||'Specialista non indicato')}</small></div><span class="badge">${x.outcome?'Completata':'Da preparare'}</span></div>${x.place?`<p><strong>Struttura:</strong> ${esc(x.place)}</p>`:''}${x.documents?`<div class="visit-box"><strong>📄 Documenti da portare</strong><p>${esc(x.documents)}</p></div>`:''}${x.questions?`<div class="visit-box questions"><strong>❓ Domande da fare</strong><p>${esc(x.questions)}</p></div>`:''}${x.outcome?`<div class="visit-box outcome"><strong>✅ Note dopo la visita</strong><p>${esc(x.outcome)}</p></div>`:''}</div><div class="card-actions"><button data-visit-prepare="${x.id}" title="Prepara visita">✨</button><button data-visit-edit="${x.id}" title="Aggiorna note">✏️</button><button data-visit-del="${x.id}" title="Elimina">🗑️</button></div></article>`).join('')||'<div class="empty-state">Nessuna visita ancora salvata.</div>';
