function closeMenu(){$('sidebar')?.classList.remove('open');$('menuBackdrop')?.classList.add('hidden')}
function toggleMenu(){const opening=!$('sidebar').classList.contains('open');$('sidebar').classList.toggle('open',opening);$('menuBackdrop').classList.toggle('hidden',!opening)}
function openQuickAdd(){$('quickAddSheet').classList.remove('hidden');$('menuBackdrop').classList.remove('hidden')}
function closeQuickAdd(){$('quickAddSheet')?.classList.add('hidden');if(!$('sidebar')?.classList.contains('open'))$('menuBackdrop')?.classList.add('hidden')}
function setBadge(id,value){const el=$(id);if(!el)return;el.textContent=value;el.classList.toggle('hidden',!value)}
function renderProfessionalNav(){if(!state.profile)return;const preg=state.profile.mode==='pregnancy';document.querySelectorAll('.pregnancy-only').forEach(x=>x.classList.toggle('hidden',!preg));document.querySelectorAll('.born-only').forEach(x=>x.classList.toggle('hidden',preg));$('sidebarChildName').textContent=state.profile.childName;$('sidebarJourneyLabel').textContent=preg?pregnancyLabel(state.profile.birthDate):ageText(state.profile.birthDate);const today=new Date().toISOString().slice(0,10);setBadge('badgeCalendario',(state.deadlines||[]).filter(x=>x.date>=today).length);setBadge('badgeVisite',(state.visits||[]).filter(x=>x.date>=today).length);setBadge('badgeDocumenti',(state.documents||[]).filter(x=>x.status==='Manca'||x.status==='Da aggiornare').length);const all=preg?activeItems():journeyItems;setBadge('badgeChecklist',all.filter(x=>!state.completed.includes(x.id)).length)}
function applyPreferences(){const p=state.preferences||{};document.body.classList.toggle('theme-dark',p.theme==='dark'||(p.theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches));document.body.classList.toggle('high-contrast',!!p.highContrast);document.body.classList.toggle('large-icons',!!p.largeIcons);document.body.classList.toggle('text-large',p.textSize==='large');document.body.classList.toggle('text-xlarge',p.textSize==='xlarge');if($('themeSelect'))$('themeSelect').value=p.theme||'system';if($('textSizeSelect'))$('textSizeSelect').value=p.textSize||'normal';if($('highContrastToggle'))$('highContrastToggle').checked=!!p.highContrast;if($('largeIconsToggle'))$('largeIconsToggle').checked=!!p.largeIcons}
function permissionLabel(p){return p==='owner'?'Amministratore':p==='editor'?'Può modificare':'Solo lettura'}
function applyMemberPermission(){const cloudMember=window.PDP_CLOUD?.getMember?.();const active=cloudMember||(state.members||[]).find(x=>x.id===state.activeMemberId),readOnly=active?.permission==='viewer';document.body.classList.toggle('read-only-mode',!!readOnly);document.querySelectorAll('form input,form select,form textarea,form button[type="submit"],.danger-btn').forEach(el=>{if(el.closest('#memberForm')||el.id==='navSearch')return;el.disabled=!!readOnly});if(readOnly&&$('syncStatus'))$('syncStatus').textContent='Modalità sola lettura'}
function renderFamilyMembers(){
 const box=$('familyMembersList');if(!box)return;state.members=state.members||[];
 const me=window.PDP_CLOUD?.getMember?.();const admin=['owner','admin'].includes(me?.permission);
 box.innerHTML=state.members.map(m=>`<article class="member-card ${m.id===state.activeMemberId?'active-member':''}"><span class="member-initial">${esc((m.name||'?').slice(0,1).toUpperCase())}</span><div class="grow"><strong>${esc(m.name)}</strong><small>${esc(m.role)} · ${permissionLabel(m.permission)}${m.email?' · '+esc(m.email):''}</small></div>${m.id===state.activeMemberId?'<span class="nav-badge">Tu</span>':admin?`<button class="mini-btn" data-member-edit="${m.id}">Gestisci</button>`:''}</article>`).join('')||'<p class="privacy-note">Nessun account familiare caricato.</p>';
 document.querySelectorAll('[data-member-edit]').forEach(b=>b.onclick=async()=>{const m=state.members.find(x=>x.id===b.dataset.memberEdit);if(!m)return;const choice=prompt(`Permesso per ${m.name}: owner, admin, editor o viewer`,m.permission||'editor');if(!choice)return;if(!['owner','admin','editor','viewer'].includes(choice))return alert('Permesso non valido.');try{await window.PDP_CLOUD.updateMember(m.id,{permission:choice});activity('Permesso modificato',`${m.name}: ${choice}`);await window.PDP_CLOUD.reload()}catch(e){alert(e.message)}});
}
function renderActivityLog(){const box=$('activityLog');if(!box)return;const rows=(state.activityLog||[]).slice(0,30);box.innerHTML=rows.map(x=>`<article class="activity-row"><span>•</span><div><strong>${esc(x.action)}</strong><small>${esc(x.by||'Utente')} · ${new Date(x.at).toLocaleString('it-IT')}${x.detail?' · '+esc(x.detail):''}</small></div></article>`).join('')||'<p class="privacy-note">Nessuna attività registrata.</p>'}
function downloadBlob(name,type,content){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500)}
function exportJson(){downloadBlob(`passo-dopo-passo-backup-${new Date().toISOString().slice(0,10)}.json`,'application/json',JSON.stringify(snapshot(),null,2));activity('Backup esportato','Formato JSON');saveLocal();renderActivityLog()}
function exportCsv(){const rows=[['Sezione','Titolo','Data','Stato','Note']];(state.visits||[]).forEach(x=>rows.push(['Visita',x.title||'',x.date||'',x.notes?'Completata':'Da preparare',x.notes||'']));(state.documents||[]).forEach(x=>rows.push(['Documento',x.name||'',x.date||'',x.status||'',x.notes||'']));(state.deadlines||[]).forEach(x=>rows.push(['Calendario',x.title||'',x.date||'','',x.notes||'']));const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\n');downloadBlob(`passo-dopo-passo-${new Date().toISOString().slice(0,10)}.csv`,'text/csv;charset=utf-8','\ufeff'+csv);activity('Dati esportati','Formato CSV');saveLocal();renderActivityLog()}
