$('navSearch').oninput=e=>{const q=e.target.value.trim().toLowerCase();document.querySelectorAll('.nav-item').forEach(x=>{const phaseHidden=(x.classList.contains('pregnancy-only')&&state.profile?.mode!=='pregnancy')||(x.classList.contains('born-only')&&state.profile?.mode==='pregnancy');x.classList.toggle('hidden',phaseHidden||!!q&&!((x.dataset.label||x.textContent).toLowerCase().includes(q)))});document.querySelectorAll('.nav-group').forEach(g=>{const visible=[...g.querySelectorAll('.nav-item')].some(x=>!x.classList.contains('hidden'));g.classList.toggle('hidden',!visible)})};

const APP_VERSION='4.1.0';let waitingWorker=null;let refreshing=false;
function showUpdate(worker){waitingWorker=worker;$('updateBanner')?.classList.remove('hidden')}
async function registerUpdater(){
  if(!('serviceWorker'in navigator))return;
  try{
    const registration=await navigator.serviceWorker.register('service-worker.js',{updateViaCache:'none'});
    if(registration.waiting&&navigator.serviceWorker.controller)showUpdate(registration.waiting);
    registration.addEventListener('updatefound',()=>{
      const worker=registration.installing;if(!worker)return;
      worker.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)showUpdate(worker)});
    });
    $('checkUpdateBtn').onclick=async()=>{const btn=$('checkUpdateBtn');btn.disabled=true;btn.textContent='Controllo…';try{await registration.update();if(!registration.waiting)btn.textContent='App aggiornata'}catch(e){btn.textContent='Controllo non riuscito'}setTimeout(()=>{btn.disabled=false;btn.textContent='Controlla aggiornamenti'},1800)};
    setInterval(()=>registration.update().catch(()=>{}),60*60*1000);
  }catch(e){console.warn('Aggiornamento PWA non disponibile',e)}
}
$('appVersion').textContent=APP_VERSION;
$('applyUpdateBtn').onclick=()=>{if(waitingWorker){$('applyUpdateBtn').disabled=true;$('applyUpdateBtn').textContent='Aggiornamento…';waitingWorker.postMessage({type:'SKIP_WAITING'})}};
$('updateLaterBtn').onclick=()=>$('updateBanner').classList.add('hidden');
navigator.serviceWorker?.addEventListener('controllerchange',()=>{if(refreshing)return;refreshing=true;location.reload()});
window.addEventListener('load',registerUpdater);
window.addEventListener('online',()=>{if(state.syncMeta?.pending)performCloudSync(false)});window.addEventListener('offline',()=>setSyncStatus('Offline: copia locale','error'));
function updateDateLabel(){const preg=$('journeyMode').value==='pregnancy';$('birthDateLabel').childNodes[0].nodeValue=preg?'Data presunta del parto':'Data di nascita'}$('journeyMode').onchange=updateDateLabel;updateDateLabel();
window.PDP_APP={
 getState:()=>snapshot(),
 replaceState:(data,options={})=>{state=Object.assign(emptyState(),data||{});state.preferences={...emptyState().preferences,...(state.preferences||{})};state.syncMeta={...emptyState().syncMeta,...(state.syncMeta||{})};state.activityLog=state.activityLog||[];state.members=state.members||[];state.documents=(state.documents||[]).map(d=>({...d,status:d.status||(d.done?'Completo':'Manca'),done:(d.status?d.status==='Completo':!!d.done),expiry:d.expiry||'',visitId:d.visitId||'',notes:d.notes||'',fileName:d.fileName||'',fileType:d.fileType||'',fileSize:d.fileSize||0,extractedText:d.extractedText||'',driveFileId:d.driveFileId||'',driveUrl:d.driveUrl||'',driveUploadedAt:d.driveUploadedAt||''}));localStorage.setItem('pdp_state',JSON.stringify(state));renderAll();if(options.fromCloud){state.syncMeta={...state.syncMeta,status:'ok',pending:false,error:'',lastSuccess:options.updatedAt||new Date().toISOString(),revision:options.revision||state.syncMeta.revision||0};saveLocal();refreshSyncUi()}},
 persist:()=>persist(true)
};
renderAll();if(state.profile&&!window.PDP_CLOUD?.isConfigured?.()){setSyncStatus(apiConfigured()?'Google collegato':'Configura Apps Script',apiConfigured()?'ok':'error');loadFromGoogle(false)}
